sys_script.script:
// Auto-assign tasks based on responsible department
var departmentAssignments = {
  'it': 'itil',
  'facilities': 'facilities_admin', 
  'hr': 'hr_admin',
  'security': 'security_admin',
  'manager': '' // Will be assigned to the actual manager
};

var dept = current.getValue('responsible_department');
if (dept && departmentAssignments[dept]) {
  var gr = new GlideRecord('sys_user');
  if (dept === 'manager') {
    // Get the manager from the parent offboarding case
    var caseGr = new GlideRecord('x_1876152_hr_off_0_offboarding_case');
    if (caseGr.get(current.getValue('offboarding_case')) && caseGr.getValue('manager')) {
      current.setValue('assigned_to', caseGr.getValue('manager'));
    }
  } else {
    // Find a user with the appropriate role
    gr.addQuery('roles', 'CONTAINS', departmentAssignments[dept]);
    gr.addQuery('active', true);
    gr.orderBy('name');
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
      current.setValue('assigned_to', gr.getUniqueValue());
    }
  }
}

// Set due date based on expected completion date
if (current.getValue('expected_completion_date')) {
  current.setValue('due_date', current.getValue('expected_completion_date'));
}
